head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gMsgSum = "";
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gEmpNo = js_emp_no; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gLdMktTpCd = js_market; // 로그인사용자의 시장구분

// 부모창(목록검색)의 접수번호
// var gAcptNo = frame.Provider("/").gAcptNo;
scwin.gAcptNo = $c.frame.path("../frame_head").scwin.gAcptNo;
scwin.gSndlocTp = $c.frame.path("../frame_head").gSndlocTpCd;
scwin.gProcsStatCd = $c.frame.path("../frame_head").scwin.gProcsStatCd; // 처리상태
scwin.gNxtTpCd = $c.frame.path("../frame_head").scwin.gNxtTpCd; // 익일당일여부
scwin.gDoc_LdMktTp = $c.frame.path("../frame_head").scwin.gDoc_LdMktTp;
scwin.gDisclsAcptTpCd = $c.frame.path("../frame_head").scwin.gDisclsAcptTpCd; // 공시접수유형
scwin.gDisclsTrnsmTpCd = $c.frame.path("../frame_head").scwin.gDisclsTrnsmTpCd; // 전송구분
scwin.gDelayYn = $c.frame.path("../frame_head").scwin.gDelayYn; // 처리지연 상태여부
scwin.gDelayFormYn = $c.frame.path("../frame_head").scwin.gDelayFormYn;
scwin.gMainFormCd = $c.frame.path("../frame_head").scwin.gMainFormCd; // 서식코드 : 확인절차 대상법인 조치안내(20151231)

// 연계공시개발
scwin.gHdcomLnkDisclsYn = $c.frame.path("../frame_head").scwin.gHdcomLnkDisclsYn;
scwin.gHdcomDisclsProcsStatCd = $c.frame.path("../frame_head").scwin.gHdcomDisclsProcsStatCd;
scwin.gSubcomDisclsProcsStatCd = $c.frame.path("../frame_head").scwin.gSubcomDisclsProcsStatCd;
scwin.gSubcomNxtddTddTpCd = $c.frame.path("../frame_head").scwin.gSubcomNxtddTddTpCd;
// 연계공시개발

scwin.gTrdHaltMsg = $c.frame.path("../frame_head").scwin.gTrdHaltMsg;
scwin.gFormWarnContn = $c.frame.path("../frame_head").scwin.gFormWarnContn; // 공동공시 유의사항
scwin.gAtsIsuYn = $c.frame.path("../frame_head").scwin.gAtsIsuYn; // ATS 거래종목 여부
scwin.gMktclsYn = $c.frame.path("../frame_head").scwin.gMktclsYn; // 장종료 여부(18:00~20:00)
scwin.gAtsTrnsmYn = $c.frame.path("../frame_head").scwin.gAtsTrnsmYn; // 거래정지 해당여부(ATS 전송여부)
scwin.gAtsTrnsmRsltCd = $c.frame.path("../frame_head").scwin.gAtsTrnsmRsltCd; // ATS 전송 결과(S_성공,E_실패,E1_실패(공시뷰어를 닫지 않은 경우))
scwin.gBatchReservYn = $c.frame.path("../frame_head").scwin.gBatchReservYn; // 예약공시 여부(Y^20시이전,N^20시이후,^대상X)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 로그인 사용자정보로 공시처리가능여부 체크
        await scwin.getApprvProcButtonYN();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_AcptProcs",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_AcptProcs=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 가우스헤더 셋팅
        const sbmOptions2 = {
            id : "sbm_dts_ReservInfo",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_ReservInfo=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 이전단계 처리상태에 따른 버튼 생성여부
        scwin.showOptButton();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_btnshow_OnLoadCompleted
 * @description dts_btnshow 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_btnshow_OnLoadCompleted = function(rowcount) {
    try {
        scwin.showApprvProcButton(dts_btnshow.getCellData(1, "DUTY_PROC_YN"), dts_btnshow.getCellData(1, "GRNL_PROC_YN"), dts_btnshow.getCellData(1, "CLOSE_YN"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10104.dts_btnshow_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_btnshow_OnLoadError
 * @description dts_btnshow 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_btnshow_OnLoadError = async function() {
    try {
        await $c.win.alert('dts_btnshow.OnFail() :' + dts_btnshow.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.dts_btnshow_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_procs_stat_OnLoadCompleted
 * @description dts_procs_stat 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_procs_stat_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name dts_procs_stat_OnLoadError
 * @description dts_procs_stat 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_procs_stat_OnLoadError = async function() {
    try {
        await $c.win.alert('dts_procs_stat.OnLoadError()' + dts_procs_stat.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.dts_procs_stat_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ATS_OnLoadCompleted
 * @description dts_ATS 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ATS_OnLoadCompleted = async function(rowcount) {
    try {
        scwin.closeload();
        const responseValue = dts_ATS.getCellData(1, "VALUE");
        const responseText = dts_ATS.getCellData(1, "TEXT");

        // alert(responseValue + "\n" + responseText);

        if (responseValue === "true") {
            scwin.gAtsTrnsmRsltCd = "S"; // ATS 전송 성공

            // 승인전송
            await scwin.sendApproval(scwin.gMsgSum);
        } else {
            scwin.gAtsTrnsmRsltCd = "E1"; // ATS 전송 실패

            await $c.win.alert("3회 이상 수신오류가 발생하여 ATS 비상연락망으로 통보(SMS, E-mail) 하였습니다.\n유선 통보 필요");

            // 비상연락망 명부 팝업
            await scwin.popupEmContactNmList();

            // 승인처리
            await scwin.dsclApproval();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.dts_ATS_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ATS_OnLoadError
 * @description dts_ATS 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ATS_OnLoadError = async function() {
    try {
        scwin.closeload();
        await $c.win.alert('dts_ATS.OnLoadError()' + dts_ATS.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.dts_ATS_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Mktcls_OnLoadCompleted
 * @description dts_Mktcls 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Mktcls_OnLoadCompleted = async function(rowcount) {
    try {
        // ATS 전송결과 업데이트
        scwin.gAtsTrnsmRsltCd = dts_Mktcls.getCellData(1, "ATS_TRNSM_RSLT_CD");
        const mktclsYn = dts_Mktcls.getCellData(1, "MKTCLS_YN"); // 장종료여부 확인
        const batchReservYn = dts_Mktcls.getCellData(1, "BATCH_RESERV_YN"); // 예약공시여부 확인

        // alert("!" + gMktclsYn + "_" + mktclsYn + "_" + gAtsTrnsmRsltCd + "_\n_" + gBatchReservYn + "_" + batchReservYn);

        if (scwin.gMktclsYn !== mktclsYn || scwin.gBatchReservYn !== batchReservYn) {
            const vUrl = $c.frame.path("../").frame_head.srcUrl;
            await $c.win.alert("장 중 여부가 변경되었습니다.\n승인 버튼을 다시 클릭해 주세요.");
            $c.frame.path("../").frame_head.srcUrl = vUrl;
        } else {
            await scwin.dsclApproval(); // 승인

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.dts_Mktcls_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Mktcls_OnLoadError
 * @description dts_Mktcls 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
