    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.dts_Mktcls_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_AcptProcs_OnSuccess
 * @description Acpt Procs On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_AcptProcs_OnSuccess = async function() {
    try {
        scwin.closeload();
        if (scwin.gDelayYn === 'Y' && Number(scwin.gDelayFormYn) > 0) {
            let vAnswer = confirm('성공적으로 승인처리 되었습니다.\n 처리지연된 공시문서입니다. \n 공시경과 사유를 입력하시겠습니까?');
            if (vAnswer === true) {
                let url = "/dsclproc/ULDSTF10502.gfm";
                let winTitle = "공시경과사유";
                // frame.CreateDialogFrame("gform", url , winTitle ,100, -500, 800, 370, "window" );    //ryu
                await $c.frame.CreateDialogFrame("STF10502", url, winTitle, 100, -500, 700, 250 + 30, "window");
            } else {
                scwin.closeParentReload(); // ryu 아래 있던 사항 위로 올렸음.

            }
        } else if (scwin.gBatchReservYn === 'Y') {
            // 20시 이전 예약공시
            await $c.win.alert("성공적으로 예약처리 되었습니다.");
            scwin.closeParentReload(); // ryu 아래 있던 사항 위로 올렸음.

        } else {
            await $c.win.alert("성공적으로 승인처리 되었습니다.");
            scwin.closeParentReload(); // ryu 아래 있던 사항 위로 올렸음.

        }

        // fn_CloseParentReload(); //ryu
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.trs_AcptProcs_OnSuccess" });
    }
};

/**
