/**
 * @method
 * @name img_approval_onclick
 * @description 「승인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_approval_onclick = async function() {
    try {
        // ATS 거래종목에 해당하는 경우 시간 체크
        if (scwin.gAtsIsuYn === 'Y') {
            await scwin.getMktclsYn();
        } else {
            await scwin.dsclApproval(); // 승인

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.img_approval_onclick" });
    }
};

/**
 * @method
 * @name img_reserve_onclick
 * @description 「유보」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_reserve_onclick = async function() {
    try {
        if (scwin.gSndlocTp === '90') {
            // 지주회사연계공시때
            await $c.win.alert("지주회사 연계공시는 유보처리를 할 수 없습니다.");
        } else {
            // 금감원 및 상장법인이 제출한 문서만 유보사유를 받고 처리함.
            if (scwin.gSndlocTp === '20' || scwin.gSndlocTp === '30') {
                let url = "/dsclproc/ULDSTF10005.gfm";
                let winTitle = "유보처리";
                await $c.frame.CreateDialogFrame("gform_reserve", url, winTitle, 100, -500, 770, 360 + 30, "window");
            } else {
                await scwin.dsclReserv();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10104.img_reserve_onclick" });
    }
};

