 * @hidden N
 */
scwin.cmb_ATS_TRNSM_YN_OnSelChange = function() {
    try {
        if (cmb_ATS_TRNSM_YN.getValue() === '') {
            scwin.disableObj("approval");
        } else {
            if (img_approval.getDisabled()) {
                scwin.enableObj("approval");
            }
            if (cmb_ATS_TRNSM_YN.getValue() === 'Y') {
                // ATS 전송여부가 전송일 때 당일전송 체크
                rdo_trnsmtp.setValue('1');
                rdo_trnsmtp.setDisabled(true);
            } else {
                rdo_trnsmtp.setDisabled(false);
            }
            rdo_trnsmtp.focus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10104.cmb_ATS_TRNSM_YN_OnSelChange" });
    }
};

