/**
 * @method
 * @name sendApproval
 * @description send Approval 처리
 * @param {*} vMsgSum vMsgSum
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendApproval = async function(vMsgSum) {
    let sMsg = "";
    let sMethod = "processDisclosureApproval";
    if (scwin.gBatchReservYn === 'Y') {
        // 20시 이전 예약공시
        sMsg = '20시 이후에 배포됩니다.(예약공시)\n';
        sMethod = "updateDisclosureBatchReserv";
    } else if (scwin.gBatchReservYn === 'N') {
        // 20시 이후 예약공시
        sMsg = '즉시 배포됩니다.\n';
    }
    sMsg += vMsgSum;
    if (confirm(sMsg)) {
        if (await scwin.getProcsSate(scwin.gAcptNo) === false) {
            scwin.closeParentReload();
            return false;
        } else {
            scwin.showload();

            // 로딩 이미지가 순식간에 나타났다 사라지거나 로딩 이미지가 그려지는 영역은 보여지는데 이미지 자체가 안보이는 경우가 있어서
            setTimeout(async function() {
                trs_AcptProcs.KeyName = "toinb_dataid4";
                const sbmOptions = {
                    id : "sbm_trs_AcptProcs",
                    action : "/DisclosureApproval.do",
                    ref : "dts_AcptProcs",
                    target : "trs_AcptProcs=body.content",
                    isProcessMsg : false
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
            }, 500);
        }
    }
};

